/// `pub(crate)` because `op_rows.rs`'s table publishes this range as `width`'s and
/// `height`'s bound: the published bound is SOURCED from the constant the
/// refusal below is written against, never retyped beside it.
pub(crate) const CANVAS_MIN: u32 = 16;
pub(crate) const CANVAS_MAX: u32 = 16384;

// ---- helpers -------------------------------------------------------------

/// A canvas dimension: inside the bounds AND even.
///
/// Even is not fussiness: H.264 and HEVC encode in macroblocks over a
/// chroma-subsampled plane, so an odd width or height is either refused by
/// the encoder or silently padded. Catching it here makes it a message
/// about the canvas field the user just typed instead of an export that
/// fails an hour later.
fn check_dimension(key: &str, value: u32) -> Result<(), String> {
    if !(CANVAS_MIN..=CANVAS_MAX).contains(&value) {
        return Err(format!(
            "{key} must be between {CANVAS_MIN} and {CANVAS_MAX}, not {value}"
        ));
    }
    if !value.is_multiple_of(2) {
        return Err(format!(
            "{key} must be even (h.264 encodes in macroblocks), not {value}"
        ));
    }
    Ok(())
}

/// Multiplies every clip's placement by the canvas size ratio, so a layout
/// built for one canvas lands in the same relative place on the next (spec
/// §6, `rescale_clips`).
///
/// `x` and `y` are per-axis offsets in canvas pixels, so each follows its
/// OWN axis ratio — that is what keeps a layer's distance from an edge
/// proportional when the aspect ratio changes too. `scale` is one uniform
/// factor and cannot follow two ratios, so it follows the SMALLER of them:
/// the same `min` Fit uses, which means a layer that fitted the old canvas
/// still fits the new one, where the larger ratio could push it off an
/// edge.
///
    /// Green screen, with the spec §5.2 example's tolerances.
    fn default() -> Self {
        Chroma {
            key: [0.0, 1.0, 0.0],
            tolerance: 0.2,
            softness: 0.1,
            spill: 0.5,
        }
    }
}

/// The most filters one layer may carry.
///
/// A SHADER BUDGET, not taste: the compositor's uniform block carries four
/// `(kind, amount)` pairs and the fragment shader applies them in a fixed
/// unrolled order, so a fifth filter has nowhere to go. `set_video` names
/// the overflow rather than dropping it — a silently ignored filter is a
/// user staring at a control that does nothing.
pub const MAX_FILTERS: usize = 4;

/// One image filter and how much of it (M3). Order matters: filters are
/// applied in the order they appear in `video.filters`, so blur-then-sepia
/// and sepia-then-blur are different pictures.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Filter {
    pub kind: FilterKind,
    /// 0 = the filter is present but does nothing, 1 = its full effect.
    pub amount: f64,
}

impl Default for Filter {
    /// Half-strength blur: the value a newly added filter takes, chosen so
    /// adding one from the inspector visibly does something without
    /// destroying the frame.
    fn default() -> Self {
        Filter {
            kind: FilterKind::Blur,
            amount: 0.5,
        }
    }

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SpotShape {
    #[default]
    Rect,
    Ellipse,
}

/// The most hidden regions one layer may carry.
///
/// A SHADER BUDGET, exactly as [`crate::model::MAX_FILTERS`] is: the
/// uniform block carries four regions and the fragment stage applies them
/// in a fixed unrolled order, so a fifth has nowhere to go. `set_video`
/// names the overflow rather than dropping it, and the reason is sharper
/// here than it is for a filter — a region the user drew over a face and
/// cannot see is not a control that does nothing, it is the face still on
/// screen.
pub const MAX_OBSCURE: usize = 4;

/// One region of the picture hidden behind a blur or a pixelation (road map
/// 2, phase 3c) — the spotlight's inverse. A face, a password field, a
/// notification that slid in halfway through the take.
///
/// The geometry is [`Spotlight`]'s frame, and the paragraph above that type
/// is its canonical statement: `x`/`y` are the region's CENTRE as an offset
/// in SOURCE pixels from the centre of the layer's cropped rect, `width`
/// and `height` its size in the same pixels. So a region rides with its
/// layer through scale, move and rotation, and stays on the face it was put
/// on. Nothing here is in canvas pixels, and a nest's transform folds into
/// the layer around it rather than into this box.
///
/// `shape` is [`SpotShape`] — the spotlight's own rect/ellipse, reused
/// rather than copied. It is the same vocabulary naming the same distance
/// field, and shared vocabulary has exactly one home (core/CLAUDE.md); if
/// the two ever have to diverge, splitting an enum is a rename, while
/// merging two is a schema migration.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct ObscureRegion {
    pub shape: SpotShape,
    }
}

/// The most stops one gradient may carry. NOT a shader budget, which is why
/// it is 8 where [`crate::model::MAX_FILTERS`] and
/// [`crate::model::MAX_OBSCURE`] are both 4: those two are SLOTS — the uniform block carries exactly four `(kind, amount)` pairs
/// and exactly four regions, and a fifth of either has nowhere to go — while
/// a gradient never reaches the fragment stage at all, since
/// `LayerRenderers.renderShape` hands the stops to `CGGradient` on the CPU,
/// which takes as many as it is given. Four here would be a real limitation
/// (a sunset, a spectrum, a brand ramp) bought for no technical reason, and
/// a cap that turns out too high costs nothing where one that turns out too
/// low is reported as a bug. It is NAMED rather than trimmed all the same,
/// the posture the other two take: a stop silently dropped from the next
/// write is a colour the user placed and can no longer see.
pub const MAX_GRADIENT_STOPS: usize = 8;

/// A gradient fill for a shape (format version 6, road map 2's phase 6) —
/// what `shape.fill`'s single colour becomes when a flat plate is not
/// enough: a sky behind a title, a brand ramp, the wash on the full-canvas
/// background clip `edit_background.rs` puts on the back track.
