        let proposed = anchorBounds.offsetBy(dx: raw.dx, dy: raw.dy)
        let result = snapper.resolve(rect: proposed)
        raw.dx += result.offset.dx
        raw.dy += result.offset.dy
        delta = raw
        guideX = result.guideX
        guideY = result.guideY
        didMove = true
    }
}

